export interface CatTrack extends Track {
  cats: string[]
}

function build(r: Raw): CatTrack {
  const [id, title, artist, duration, cats] = r
  return {
    id,
    source: 'youtube',
    title,
    artist,
    artistHandle: '',
    artwork: `https://i.ytimg.com/vi/${id}/hqdefault.jpg`,
    artworkLarge: `https://i.ytimg.com/vi/${id}/maxresdefault.jpg`,
    duration,
    playCount: 0,
    streamUrl: '',
    cats: cats ? cats.split('|') : [],
  }
}

export const BOLLYWOOD_TRACKS: CatTrack[] = RAW.map(build)

/** Songs tagged with a given chip label (e.g. "Arijit Singh"). */
export function bollywoodByCategory(label: string): CatTrack[] {
  return BOLLYWOOD_TRACKS.filter((t) => t.cats.includes(label))
}
